push.css:
.fxs .uk{--pushA:#F7EDD3;--pushB:#1E3F73;--pushC:#C8402C;--rim:#86A7C9;--rimD:#1E3F73}
.fxs .push.uk{--pr:4px;background:none;border-radius:4px;box-shadow:none;filter:drop-shadow(0 8px 0 rgba(20,34,60,.45)) drop-shadow(0 16px 22px rgba(0,0,0,.35))}
.fxs .push.uk span{font:400 42px/1 "Shippori Antique B1",serif;letter-spacing:.08em;color:#2A2420;text-shadow:0 2px 0 #FFFFFF,0 0 6px rgba(255,255,255,.6)}
.fxs .push.uk::after{inset:-20px;border-radius:14px;border-color:rgba(134,167,201,.95)}
.fxs .uk .ukf{position:absolute;left:-20px;top:-24px;width:230px;height:132px;pointer-events:none;font-style:normal;z-index:-1}
.fxs .uk .ukf svg{display:block;width:230px;height:132px;overflow:visible}
.fxs .uk .ukd{position:absolute;left:-40px;top:-70px;width:280px;height:210px;pointer-events:none;z-index:3;font-style:normal}
.fxs .uk .ukd svg{display:block;width:280px;height:210px;overflow:visible}
.fxs .uk .ukbo{animation:fxukBo 2.4s ease-in-out infinite alternate}
@keyframes fxukBo{from{transform:translateY(-4px) rotate(-6deg)}to{transform:translateY(4px) rotate(6deg)}}
.fxs .uk .uktw{transform-box:fill-box;transform-origin:50% 50%;animation:fxukTw 2.2s ease-in-out infinite}
